                    .body = try self.allocator.dupe(u8, e.body),
                };
            }
            return .{ .rows = out, .total = p.total };
        }
        const total = try q.Count();
        var found = try q.All();
        defer {
            for (found.items) |*p| {
                zent.codegen.deinitEntity(infos, PostInfo, p, self.allocator);
