    /// Transactional checkout (zent TxClient): cart → Order + OrderItems,
    /// stock decremented in the same transaction, cart cleared on commit.
    /// Returns the new order id. Errors roll back everything.
    pub fn checkout(self: *@This(), user_id: i64) !i64 {
        var txc = try zent.codegen.client.beginTx(infos, self.client);
        defer txc.deinit();
        errdefer txc.rollback() catch {};

        // 1. read the cart inside the tx
        var q = txc.client.cart_item.Query();
        defer q.deinit();
        const cpreds = txc.client.cart_item.predicates;
        _ = try q.Where(.{cpreds.user_idEQ(.{ .int = user_id })});
        var cart = try q.All();
        defer {
            for (cart.items) |*c| {
                zent.codegen.deinitEntity(infos, CartItemInfo, c, self.allocator);
            }
            cart.deinit();
        }
        if (cart.items.len == 0) return error.EmptyCart;

        // 2. verify stock + compute total (snapshot pricing)
        var total_cents: i64 = 0;
        for (cart.items) |c| {
            const p = try self.getProductById(c.product_id orelse 0) orelse return error.ProductNotFound;
            defer self.freeProduct(p);
            if (p.stock < c.qty) return error.InsufficientStock;
            total_cents += p.price_cents * c.qty;
        }

        // 3. create the order (data_scope entity: attach a context; production
        //    would carry the buyer's request scope, empty ctx = allow-all)
        var ob = try txc.client.order.withContext(.{}).Create();
        defer ob.deinit();
        _ = try ob.setFieldValue("buyer_id", user_id);
        _ = try ob.setFieldValue("status", "pending");
        _ = try ob.setFieldValue("total_cents", total_cents);
        var order_ent = try ob.Save();
        defer zent.codegen.deinitEntity(infos, OrderInfo, &order_ent, self.allocator);
        const order_id = order_ent.id;

        // 4. per item: decrement stock + snapshot OrderItem
        for (cart.items) |c| {
            const p = try self.getProductById(c.product_id orelse 0) orelse return error.ProductNotFound;
            defer self.freeProduct(p);

            var ub = txc.client.product.Update();
            defer ub.deinit();
            _ = try ub.Where(.{txc.client.product.predicates.idEQ(.{ .int = c.product_id orelse 0 })});
            _ = try ub.setExprArgs("stock", "stock - ?", &.{.{ .int = c.qty }});
            _ = try ub.Save();

            var iob = try txc.client.order_item.Create();
            defer iob.deinit();
            _ = try iob.setFieldValue("order_id", order_id);
            _ = try iob.setFieldValue("product_id", c.product_id orelse 0);
            _ = try iob.setFieldValue("qty", c.qty);
            _ = try iob.setFieldValue("price_cents", p.price_cents);
            var oi_ent = try iob.Save();
            defer zent.codegen.deinitEntity(infos, OrderItemInfo, &oi_ent, self.allocator);
            _ = oi_ent.id;
        }

        // 5. clear the cart (same tx)
        var db = try txc.client.cart_item.BulkDelete();
        defer db.deinit();
        _ = try db.Where(.{txc.client.cart_item.predicates.user_idEQ(.{ .int = user_id })});
        _ = try db.Exec();

        try txc.commit();
        return order_id;
    }

    pub const FeedItem = struct {
        post_id: i64,
        author_id: i64,
        author_handle: []const u8,
        body: []const u8,
    };

    /// Followees' posts (newest first) with author handle.
    /// Demonstrates zent `QueryEdge`: authors are batch-loaded in ONE query
    /// (no N+1) from the `author` From edge declared in schema.zent.
    /// Caller owns the slice + each handle; free with `freeFeed`.
    pub fn feedFor(self: *@This(), user_id: i64, limit: usize) ![]FeedItem {
        const alloc = self.allocator;

        // 1. followee ids
        var fq = self.client.follow.Query();
        defer fq.deinit();
        const fpreds = self.client.follow.predicates;
        _ = try fq.Where(.{fpreds.follower_idEQ(.{ .int = user_id })});
        var follows = try fq.All();
        defer {
            for (follows.items) |*f| zent.codegen.deinitEntity(infos, FollowInfo, f, alloc);
            follows.deinit();
        }
        if (follows.items.len == 0) return alloc.alloc(FeedItem, 0);

        var followee_ids: [64]i64 = undefined;
        var followee_count: usize = 0;
        for (follows.items) |f| {
            if (followee_count >= followee_ids.len) break;
            followee_ids[followee_count] = f.followee_id orelse 0;
            followee_count += 1;
        }

        // 2. posts by those authors (IN query), newest first
        // NB: zent WhereIn() still uses the 2-arg append in v0.28 (Zig 0.17
        //     incompatible); sql.In() builds the same predicate without it.
        var values_buf: [64]zent.sql.Value = undefined;
        for (followee_ids[0..followee_count], 0..) |id, i| values_buf[i] = .{ .int = id };
        var pq = self.client.post.Query();
        defer pq.deinit();
        _ = try pq.Where(.{zent.sql.In("author_id", values_buf[0..followee_count])});
        _ = try pq.OrderBy(&.{.{ .column = .{ .name = "id", .desc = true } }});
        _ = pq.Limit(limit);
        var posts = try pq.All();
        defer {
            for (posts.items) |*p| zent.codegen.deinitEntity(infos, PostInfo, p, alloc);
            posts.deinit();
        }

        // 3. batch-load authors via QueryEdge (single query)
        var post_ids: [64]i64 = undefined;
        const m = @min(posts.items.len, post_ids.len);
        for (posts.items[0..m], 0..) |p, i| post_ids[i] = p.id;
        var authors = try self.client.post.QueryEdge("author", post_ids[0..m]);
        defer {
            for (authors.items) |*a| zent.codegen.deinitEntity(infos, UserInfo, a, alloc);
            authors.deinit();
        }

        var out = try alloc.alloc(FeedItem, m);
        errdefer alloc.free(out);
        for (posts.items[0..m], 0..) |p, i| {
            var handle: []const u8 = "?";
            for (authors.items) |a| {
                if (a.id == (p.author_id orelse 0)) {
                    handle = a.handle;
                    break;
                }
            }
            out[i] = .{
                .post_id = p.id,
                .author_id = p.author_id orelse 0,
                .author_handle = try alloc.dupe(u8, handle),
                .body = try alloc.dupe(u8, p.body),
            };
        }
        return out;
    }

    pub fn freeFeed(self: *@This(), rows: []FeedItem) void {
        for (rows) |r| {
            self.allocator.free(r.author_handle);
            self.allocator.free(r.body);
        }
        self.allocator.free(rows);
    }

    pub const RecommendRow = struct {
        user_id: i64,
        handle: []const u8,
    };

    /// Friend-of-friend suggestion (2-hop via Follow rows), excluding self and
    /// already-followed users. Demonstrates graph traversal over the social
    /// edge with plain queries + IN batch loading.
    /// Caller owns slice + handles; free with `freeRecommend`.
    pub fn recommendFor(self: *@This(), user_id: i64, limit: usize) ![]RecommendRow {
        const alloc = self.allocator;

        var fq = self.client.follow.Query();
        defer fq.deinit();
        const fpreds = self.client.follow.predicates;
        _ = try fq.Where(.{fpreds.follower_idEQ(.{ .int = user_id })});
        var follows = try fq.All();
        defer {
            for (follows.items) |*f| zent.codegen.deinitEntity(infos, FollowInfo, f, alloc);
            follows.deinit();
        }

        var followee_ids: [64]i64 = undefined;
        var followee_count: usize = 0;
        for (follows.items) |f| {
            if (followee_count >= followee_ids.len) break;
            followee_ids[followee_count] = f.followee_id orelse 0;
            followee_count += 1;
        }

        // 2-hop: users followed by my followees (exclude self + already followed)
        var cand_ids: [64]i64 = undefined;
        var cand_count: usize = 0;
        for (followee_ids[0..followee_count]) |fid| {
            var hq = self.client.follow.Query();
            defer hq.deinit();
            _ = try hq.Where(.{fpreds.follower_idEQ(.{ .int = fid })});
            var hops = try hq.All();
            defer {
                for (hops.items) |*h| zent.codegen.deinitEntity(infos, FollowInfo, h, alloc);
                hops.deinit();
            }
            for (hops.items) |h| {
                const cid = h.followee_id orelse 0;
                if (cid == user_id) continue;
                var already = false;
                for (followee_ids[0..followee_count]) |f2| {
                    if (f2 == cid) already = true;
                }
                if (already) continue;
                var dup = false;
                for (cand_ids[0..cand_count]) |c| {
                    if (c == cid) dup = true;
                }
                if (dup or cand_count >= cand_ids.len) continue;
                cand_ids[cand_count] = cid;
                cand_count += 1;
            }
        }

        // batch-load candidate users (sql.In, see feed note re: WhereIn)
        var user_values: [64]zent.sql.Value = undefined;
        for (cand_ids[0..cand_count], 0..) |cid, i| user_values[i] = .{ .int = cid };
        var uq = self.client.user.Query();
        defer uq.deinit();
        _ = try uq.Where(.{zent.sql.In("id", user_values[0..cand_count])});
        var users = try uq.All();
        defer {
            for (users.items) |*u| zent.codegen.deinitEntity(infos, UserInfo, u, alloc);
            users.deinit();
        }

        const m = @min(cand_count, limit);
        var out = try alloc.alloc(RecommendRow, m);
        errdefer alloc.free(out);
        for (cand_ids[0..m], 0..) |cid, i| {
            var handle: []const u8 = "?";
            for (users.items) |u| {
                if (u.id == cid) {
                    handle = u.handle;
                    break;
                }
            }
            out[i] = .{ .user_id = cid, .handle = try alloc.dupe(u8, handle) };
        }
        return out;
    }

    pub fn freeRecommend(self: *@This(), rows: []RecommendRow) void {
        for (rows) |r| self.allocator.free(r.handle);
        self.allocator.free(rows);
    }

    /// Row-level security demo (zent data_scope): only `user_id`'s own orders
    /// are returned. The scope predicate is injected automatically from the
    /// `policy: data_scope` Schema declaration — no hand-written WHERE.
    /// Caller owns slice + status strings; free with `freeScopedOrders`.
    pub const ScopedOrderRow = struct {
        id: i64,
        buyer_id: i64,
        status: []const u8,
        total_cents: i64,
    };

    pub fn listOrdersScoped(self: *@This(), user_id: i64) ![]ScopedOrderRow {
        var scope = zent.data_scope.DataScopeFilter.init("dept_id", "buyer_id", .self_, .{ .user_id = user_id });
        const scoped = self.client.order.withContext(scope.context(.{ .user_id = user_id }));
        var q = scoped.Query();
        defer q.deinit();
        _ = try q.OrderBy(&.{.{ .column = .{ .name = "id", .desc = true } }});
        var found = try q.All();
        defer {
            for (found.items) |*o| zent.codegen.deinitEntity(infos, OrderInfo, o, self.allocator);
            found.deinit();
        }
        var out = try self.allocator.alloc(ScopedOrderRow, found.items.len);
        errdefer self.allocator.free(out);
        for (found.items, 0..) |o, i| {
            out[i] = .{
                .id = o.id,
                .buyer_id = o.buyer_id orelse 0,
                .status = try self.allocator.dupe(u8, o.status),
                .total_cents = o.total_cents,
            };
        }
        return out;
    }

    pub fn freeScopedOrders(self: *@This(), rows: []ScopedOrderRow) void {
        for (rows) |r| self.allocator.free(r.status);
        self.allocator.free(rows);
    }

    /// Lifecycle hook example (zent runtime.hook): runs before every Order
    /// create. To enable: in `init`, switch `const client` → `var client`
    /// and add `client.order = client.order.withHooks(&.{.{ .op = .create,
    /// .before = orderBeforeCreate }});` inside the hook-wiring zone.
    pub fn orderBeforeCreate(ctx: *zent.runtime.hook.HookContext) zent.runtime.hook.HookError!void {
        // example guard: reject negative totals
        for (ctx.mutated orelse &.{}) |v| {
            if (v == .int and v.int < 0) return error.ValidationFailed;
        }
        return;
    }
